1	// Package log implements an append-only, batch-commit segmented log.
2	//
3	// A writer stages a batch of opaque records with Append and publishes it
4	// atomically with Commit, or publishes several staged batches atomically
5	// with CommitGroup. Readers only ever see committed batches, in strictly
6	// increasing sequence order starting at 1. Reads locate each batch
7	// through a segment-level index that Open rebuilds from the segment
8	// files, so losing the index never loses data.
9	package log
10	
11	import (
12		"errors"
13		"fmt"
14		"os"
15		"path/filepath"
16		"sort"
17		"strconv"
18		"strings"
19		"sync"
20	)
21	
22	var (
23		// ErrNotCommitted is returned when reading a sequence that has been
24		// staged with Append but not yet committed.
25		ErrNotCommitted = errors.New("log: batch not committed")
26		// ErrUnknownBatch is returned for sequence 0, sequences that were
27		// never reserved, sequences beyond the reserved range, and batches
28		// that have already been committed.
29		ErrUnknownBatch = errors.New("log: unknown batch")
30		// ErrCorruptSegment is returned when a segment file fails validation
31		// while opening or scanning the log.
32		ErrCorruptSegment = errors.New("log: corrupt segment")
33		// ErrInvalidOptions is returned by Open when the options are not
34		// usable, e.g. a non-positive segment capacity.
35		ErrInvalidOptions = errors.New("log: invalid options")
36		// ErrSyncFailed is returned by Commit and CommitGroup when
37		// Options.Sync is set and fsyncing the segment file fails. The
38		// batches stay staged and keep their reserved sequences; committing
39		// them again retries.
40		ErrSyncFailed = errors.New("log: sync failed")
41	)
42	
43	var errClosed = errors.New("log: closed")
44	
45	// syncFile fsyncs a segment file. It is a variable so tests can
46	// simulate sync failures.
47	var syncFile = func(f *os.File) error { return f.Sync() }
48	
49	// Options configures a Log opened with Open.
50	type Options struct {
51		// SegmentBytes is the capacity of one segment file in bytes. Once a
52		// non-empty segment would exceed it, the log rolls to a new segment.
53		// A single batch or group larger than the capacity occupies its own
54		// segment. Must be positive.
55		SegmentBytes int
56		// Sync makes Commit and CommitGroup fsync the segment file before
57		// returning, so a returned commit is durable.
58		Sync bool
59	}
60	
61	// Batch is a group of records identified by a single sequence number.
62	// A Batch returned by Append is staged; after Commit or CommitGroup it
63	// is readable.
64	type Batch struct {
65		seq     uint64
66		records [][]byte
67		owner   *Log
68	}
69	
70	// Seq returns the sequence number reserved for the batch.
71	func (b Batch) Seq() uint64 { return b.seq }
72	
73	// Records returns a copy of the batch's records.
74	func (b Batch) Records() [][]byte { return copyRecords(b.records) }
75	
76	// Segment describes one segment file by the committed sequences it holds.
77	type Segment struct {
78		FirstSeq uint64
79		LastSeq  uint64
80	}
81	
82	// entryRef locates one committed batch body inside a segment file. The
83	// index is rebuilt from the segment files every time the log opens, so
84	// its loss or invalidation is always safe.
85	type entryRef struct {
86		seg    int // segment file number
87		off    int // offset of the batch body within the segment
88		length int // length of the batch body
89	}
90	
91	// Log is an append-only batch-commit log stored in a directory of
92	// segment files. It is safe for concurrent use, but the writer side is
93	// expected to be a single goroutine (see README Limits).
94	type Log struct {
95		dir  string
96		opts Options
97	
98		mu         sync.Mutex
99		file       *os.File // current segment, nil until first write
100		fileSize   int
101		segIndex   int // index of the current segment file, 0 = none yet
102		curBatches int // committed batches in the current segment
103		nextSeq    uint64
104		staged     map[uint64][][]byte
105		index      map[uint64]entryRef
106		segs       []Segment // segments holding at least one committed batch
107		closed     bool
108	}
109	
110	// Open opens the log in dir, creating the directory if needed. Existing
111	// segments are validated and their committed batches become readable,
112	// and the segment-level index is rebuilt from them. A half-written tail
113	// of the last segment — the remnant of a crash mid-write — is replaced
114	// by a durable hole marker without error and its reserved sequences stay
115	// permanent holes across reopens; any other inconsistency is
116	// ErrCorruptSegment.
117	func Open(dir string, opts Options) (*Log, error) {
118		if opts.SegmentBytes <= 0 {
119			return nil, ErrInvalidOptions
120		}
121		if err := os.MkdirAll(dir, 0o755); err != nil {
122			return nil, err
123		}
124		entries, err := os.ReadDir(dir)
125		if err != nil {
126			return nil, err
127		}
128		var indices []int
129		for _, e := range entries {
130			if e.IsDir() || !strings.HasSuffix(e.Name(), ".seg") {
131				continue
132			}
133			n, err := strconv.Atoi(strings.TrimSuffix(e.Name(), ".seg"))
134			if err != nil {
135				continue
136			}
137			indices = append(indices, n)
138		}
139		sort.Ints(indices)
140	
141		l := &Log{
142			dir:     dir,
143			opts:    opts,
144			nextSeq: 1,
145			staged:  make(map[uint64][][]byte),
146			index:   make(map[uint64]entryRef),
147		}
148		for i, n := range indices {
149			data, err := os.ReadFile(l.segmentPath(n))
150			if err != nil {
151				return nil, err
152			}
153			batches, holes, tail, err := parseSegment(data)
154			if err != nil {
155				return nil, err
156			}
157			if tail != nil && i != len(indices)-1 {
158				// A half-written tail is a crash remnant only in the
159				// last segment; anywhere else it is tampering.
160				return nil, ErrCorruptSegment
161			}
162			l.curBatches = len(batches)
163			if len(batches) > 0 {
164				seg := Segment{FirstSeq: ^uint64(0)}
165				for _, pb := range batches {
166					l.index[pb.seq] = entryRef{seg: n, off: pb.off, length: pb.length}
167					if pb.seq < seg.FirstSeq {
168						seg.FirstSeq = pb.seq
169					}
170					if pb.seq > seg.LastSeq {
171						seg.LastSeq = pb.seq
172					}
173				}
174				l.segs = append(l.segs, seg)
175				if seg.LastSeq >= l.nextSeq {
176					l.nextSeq = seg.LastSeq + 1
177				}
178			}
179			if tail != nil {
180				// Replace the torn entry with a durable hole marker so
181				// its reserved sequences stay permanent holes: the
182				// crashed batches stay staged forever and their
183				// sequences are never reused, even across reopens.
184				if err := l.rewriteTail(n, tail.off, tail.seqs); err != nil {
185					return nil, err
186				}
187				holes = append(holes, tail.seqs...)
188			}
189			for _, seq := range holes {
190				if seq == 0 {
191					continue
192				}
193				if _, ok := l.index[seq]; !ok {
194					l.staged[seq] = nil
195				}
196				if seq >= l.nextSeq {
197					l.nextSeq = seq + 1
198				}
199			}
200		}
201		if len(indices) > 0 {
202			l.segIndex = indices[len(indices)-1]
203			if err := l.openCurrent(); err != nil {
204				return nil, err
205			}
206		}
207		return l, nil
208	}
209	
210	// Append stages a batch of records and reserves the next sequence number
211	// for it. The batch becomes readable only after Commit or CommitGroup.
212	func (l *Log) Append(records [][]byte) (Batch, error) {
213		l.mu.Lock()
214		defer l.mu.Unlock()
215		if l.closed {
216			return Batch{}, errClosed
217		}
218		recs := copyRecords(records)
219		seq := l.nextSeq
220		l.nextSeq++
221		l.staged[seq] = recs
222		return Batch{seq: seq, records: recs, owner: l}, nil
223	}
224	
225	// Commit makes a staged batch durable and readable, and returns its
226	// reserved sequence number. Committing a batch that is not staged —
227	// including one already committed — returns ErrUnknownBatch. With
228	// Options.Sync a returned commit is durable; if the fsync fails Commit
229	// returns ErrSyncFailed and the batch stays staged, keeping its
230	// reserved sequence for a retry.
231	func (l *Log) Commit(b Batch) (uint64, error) {
232		l.mu.Lock()
233		defer l.mu.Unlock()
234		if l.closed {
235			return 0, errClosed
236		}
237		recs, ok := l.staged[b.seq]
238		if !ok || b.owner != l {
239			return 0, ErrUnknownBatch
240		}
241		entry := encodeBatch(b.seq, recs)
242		off, err := l.writeEntry(entry)
243		if err != nil {
244			return 0, err
245		}
246		if l.opts.Sync {
247			if err := syncFile(l.file); err != nil {
248				// The batch stays staged and keeps its reserved sequence;
249				// a later Commit retries. Drop the un-synced entry so the
250				// retry cannot duplicate it on disk.
251				l.file.Truncate(int64(off))
252				l.fileSize = off
253				return 0, fmt.Errorf("%w: %v", ErrSyncFailed, err)
254			}
255		}
256		delete(l.staged, b.seq)
257		l.index[b.seq] = entryRef{seg: l.segIndex, off: off + len(segmentMagic), length: len(entry) - len(segmentMagic) - 4}
258		l.commitSpan(b.seq, b.seq, 1)
259		return b.seq, nil
260	}
261	
262	// CommitGroup makes several staged batches durable and readable as one
263	// atomic unit: a single write and, with Options.Sync, a single fsync
264	// covering the whole group. Each batch keeps the sequence it reserved at
265	// Append, and the batches become visible in that reserved order — the
266	// merge never reorders them. If any batch is not staged — including one
267	// already committed — nothing is written and the error is
268	// ErrUnknownBatch. If the fsync fails, the written bytes are rolled back
269	// and every batch stays staged with its reserved sequence; the error is
270	// ErrSyncFailed and retrying the group commits it without duplicating
271	// entries. A crash can never leave half of the group visible: the group
272	// is either wholly durable or wholly staged, and sequences reserved by a
273	// torn group stay permanent holes.
274	func (l *Log) CommitGroup(batches []Batch) ([]uint64, error) {
275		l.mu.Lock()
276		defer l.mu.Unlock()
277		if l.closed {
278			return nil, errClosed
279		}
280		if len(batches) == 0 {
281			return nil, nil
282		}
283		members := make([]groupMember, len(batches))
284		seqs := make([]uint64, len(batches))
285		seen := make(map[uint64]struct{}, len(batches))
286		for i, b := range batches {
287			recs, ok := l.staged[b.seq]
288			if !ok || b.owner != l {
289				return nil, ErrUnknownBatch
290			}
291			if _, dup := seen[b.seq]; dup {
292				return nil, ErrUnknownBatch
293			}
294			seen[b.seq] = struct{}{}
295			members[i] = groupMember{seq: b.seq, records: recs}
296			seqs[i] = b.seq
297		}
298		entry, offs, lens := encodeGroup(members)
299		base, err := l.writeEntry(entry)
300		if err != nil {
301			return nil, err
302		}
303		if l.opts.Sync {
304			if err := syncFile(l.file); err != nil {
305				// Every batch stays staged and keeps its reserved
306				// sequence; a later CommitGroup retries. Drop the
307				// un-synced group entry so the retry cannot duplicate it.
308				l.file.Truncate(int64(base))
309				l.fileSize = base
310				return nil, fmt.Errorf("%w: %v", ErrSyncFailed, err)
311			}
312		}
313		first, last := seqs[0], seqs[0]
314		for i, m := range members {
315			delete(l.staged, m.seq)
316			l.index[m.seq] = entryRef{seg: l.segIndex, off: base + offs[i], length: lens[i]}
317			if m.seq < first {
318				first = m.seq
319			}
320			if m.seq > last {
321				last = m.seq
322			}
323		}
324		l.commitSpan(first, last, len(members))
325		return seqs, nil
326	}
327	
328	// Read returns the records of the committed batch with the given
329	// sequence, located directly through the segment-level index. A staged
330	// but uncommitted sequence yields ErrNotCommitted; sequence 0,
331	// never-reserved sequences, and sequences beyond the reserved range
332	// yield ErrUnknownBatch.
333	func (l *Log) Read(seq uint64) ([][]byte, error) {
334		l.mu.Lock()
335		defer l.mu.Unlock()
336		if l.closed {
337			return nil, errClosed
338		}
339		if _, ok := l.index[seq]; !ok {
340			if _, ok := l.staged[seq]; ok {
341				return nil, ErrNotCommitted
342			}
343			return nil, ErrUnknownBatch
344		}
345		return l.readLocked(seq)
346	}
347	
348	// Scan replays committed batches with sequence >= from in increasing
349	// sequence order, stopping at the first error returned by fn. The
350	// replay is a consistent snapshot: batches committed during the replay
351	// are invisible to it.
352	func (l *Log) Scan(from uint64, fn func(Batch) error) error {
353		l.mu.Lock()
354		if l.closed {
355			l.mu.Unlock()
356			return errClosed
357		}
358		seqs := make([]uint64, 0, len(l.index))
359		for seq := range l.index {
360			if seq >= from {
361				seqs = append(seqs, seq)
362			}
363		}
364		sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
365		batches := make([]Batch, 0, len(seqs))
366		for _, seq := range seqs {
367			records, err := l.readLocked(seq)
368			if err != nil {
369				l.mu.Unlock()
370				return err
371			}
372			batches = append(batches, Batch{seq: seq, records: records, owner: l})
373		}
374		l.mu.Unlock()
375		for _, b := range batches {
376			if err := fn(b); err != nil {
377				return err
378			}
379		}
380		return nil
381	}
382	
383	// Segments lists the segments that hold committed batches, in file
384	// order, each with its first and last committed sequence.
385	func (l *Log) Segments() []Segment {
386		l.mu.Lock()
387		defer l.mu.Unlock()
388		out := make([]Segment, len(l.segs))
389		copy(out, l.segs)
390		return out
391	}
392	
393	// Close closes the current segment file. The log must not be used
394	// afterwards.
395	func (l *Log) Close() error {
396		l.mu.Lock()
397		defer l.mu.Unlock()
398		if l.closed {
399			return nil
400		}
401		l.closed = true
402		if l.file != nil {
403			return l.file.Close()
404		}
405		return nil
406	}
407	
408	// readLocked loads the records of a committed batch through the index.
409	// The caller must hold l.mu. The returned records are freshly decoded,
410	// so callers can mutate them without affecting the log.
411	func (l *Log) readLocked(seq uint64) ([][]byte, error) {
412		ref := l.index[seq]
413		f, err := os.Open(l.segmentPath(ref.seg))
414		if err != nil {
415			return nil, err
416		}
417		defer f.Close()
418		body := make([]byte, ref.length)
419		if _, err := f.ReadAt(body, int64(ref.off)); err != nil {
420			return nil, err
421		}
422		got, records, err := decodeBody(body)
423		if err != nil {
424			return nil, err
425		}
426		if got != seq {
427			return nil, ErrCorruptSegment
428		}
429		return records, nil
430	}
431	
432	// commitSpan records n newly committed batches covering sequences
433	// [first, last] in the segment listing.
434	func (l *Log) commitSpan(first, last uint64, n int) {
435		if l.curBatches == 0 {
436			l.segs = append(l.segs, Segment{FirstSeq: first, LastSeq: last})
437		} else {
438			seg := &l.segs[len(l.segs)-1]
439			if first < seg.FirstSeq {
440				seg.FirstSeq = first
441			}
442			if last > seg.LastSeq {
443				seg.LastSeq = last
444			}
445		}
446		l.curBatches += n
447	}
448	
449	// rewriteTail drops a torn tail from segment n and, when the torn entry
450	// carried recoverable sequences, replaces it with a synced hole marker
451	// so the reserved sequences stay permanent holes across reopens.
452	func (l *Log) rewriteTail(n, off int, seqs []uint64) error {
453		path := l.segmentPath(n)
454		if err := os.Truncate(path, int64(off)); err != nil {
455			return err
456		}
457		keep := make([]uint64, 0, len(seqs))
458		for _, seq := range seqs {
459			if seq > 0 {
460				keep = append(keep, seq)
461			}
462		}
463		if len(keep) == 0 {
464			return nil
465		}
466		f, err := os.OpenFile(path, os.O_WRONLY|os.O_APPEND, 0)
467		if err != nil {
468			return err
469		}
470		if _, err := f.Write(encodeHoles(keep)); err != nil {
471			f.Close()
472			return err
473		}
474		if err := f.Sync(); err != nil {
475			f.Close()
476			return err
477		}
478		return f.Close()
479	}
480	
481	// writeEntry appends one encoded entry to the current segment, rolling
482	// to a new segment when the current one is non-empty and would exceed
483	// the configured capacity, and returns the offset the entry was
484	// written at.
485	func (l *Log) writeEntry(entry []byte) (int, error) {
486		if l.file != nil && l.fileSize > 0 && l.fileSize+len(entry) > l.opts.SegmentBytes {
487			if err := l.file.Close(); err != nil {
488				return 0, err
489			}
490			l.file = nil
491			l.segIndex++
492			l.curBatches = 0
493		}
494		if l.file == nil {
495			if l.segIndex == 0 {
496				l.segIndex = 1
497			}
498			if err := l.openCurrent(); err != nil {
499				return 0, err
500			}
501		}
502		off := l.fileSize
503		n, err := l.file.Write(entry)
504		if err != nil {
505			return 0, err
506		}
507		l.fileSize += n
508		return off, nil
509	}
510	
511	func (l *Log) openCurrent() error {
512		f, err := os.OpenFile(l.segmentPath(l.segIndex), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
513		if err != nil {
514			return err
515		}
516		st, err := f.Stat()
517		if err != nil {
518			f.Close()
519			return err
520		}
521		l.file = f
522		l.fileSize = int(st.Size())
523		return nil
524	}
525	
526	func (l *Log) segmentPath(index int) string {
527		return filepath.Join(l.dir, fmt.Sprintf("%06d.seg", index))
528	}
529	
530	func copyRecords(records [][]byte) [][]byte {
531		out := make([][]byte, len(records))
532		for i, r := range records {
533			cp := make([]byte, len(r))
534			copy(cp, r)
535			out[i] = cp
536		}
537		return out
538	}
539

