9	// On-disk entry layouts, all integers little-endian. A segment file is a
10	// sequence of entries of three kinds:
11	//
12	// Single batch, written by Commit ("BCL1"):
13	//
14	//	magic   4 bytes  "BCL1"
15	//	seq     8 bytes  batch sequence number
16	//	count   4 bytes  number of records
17	//	records count × (4-byte length + opaque bytes)
18	//	crc32   4 bytes  IEEE checksum of everything before it
19	//
20	// Batch group, written by CommitGroup as one atomic unit ("BCLG"):
21	//
22	//	magic   4 bytes  "BCLG"
23	//	count   4 bytes  number of batches in the group
24	//	batches count × (8-byte seq + 4-byte record count + records)
25	//	crc32   4 bytes  IEEE checksum of everything before it
26	//
27	// Hole marker, written by crash recovery to make the sequences reserved
28	// by a torn tail permanent ("BCLH"):
29	//
30	//	magic   4 bytes  "BCLH"
31	//	count   4 bytes  number of reserved sequences
32	//	seqs    count × 8 bytes
33	//	crc32   4 bytes  IEEE checksum of everything before it
34	//
35	// The trailing checksum makes tampering detectable as ErrCorruptSegment
36	// when the segment is parsed. A torn write left by a crash is instead
37	// reported as a tail: a strict prefix of a valid entry, never a full
38	// entry with a bad checksum. A group entry is durable only as a whole —
39	// a truncated group is a tail and none of its batches become visible.
40	var (
41		segmentMagic = []byte{'B', 'C', 'L', '1'}
42		groupMagic   = []byte{'B', 'C', 'L', 'G'}
43		holeMagic    = []byte{'B', 'C', 'L', 'H'}
44	)
45	
46	const entryHeaderLen = 4 + 8 + 4
47	
48	// groupMember is one staged batch inside a group commit.
49	type groupMember struct {
50		seq     uint64
51		records [][]byte
52	}
53	
54	func encodeBatch(seq uint64, records [][]byte) []byte {
55		size := entryHeaderLen + 4
56		for _, r := range records {
57			size += 4 + len(r)
58		}
59		buf := make([]byte, 0, size)
60		buf = append(buf, segmentMagic...)
61		var tmp [8]byte
62		binary.LittleEndian.PutUint64(tmp[:], seq)
63		buf = append(buf, tmp[:]...)
64		binary.LittleEndian.PutUint32(tmp[:4], uint32(len(records)))
65		buf = append(buf, tmp[:4]...)
66		for _, r := range records {
67			binary.LittleEndian.PutUint32(tmp[:4], uint32(len(r)))
68			buf = append(buf, tmp[:4]...)
69			buf = append(buf, r...)
70		}
71		binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(buf))
72		return append(buf, tmp[:4]...)
73	}
74	
75	// encodeGroup encodes a batch group as a single entry. It also returns,
76	// for each member, the offset and length of its decodable body (seq +
77	// record count + records) relative to the start of the entry, so the
78	// index can point straight at one member of the group.
79	func encodeGroup(members []groupMember) (entry []byte, offs []int, lens []int) {
80		size := 4 + 4 + 4
81		for _, m := range members {
82			size += 8 + 4
83			for _, r := range m.records {
84				size += 4 + len(r)
85			}
86		}
87		buf := make([]byte, 0, size)
88		buf = append(buf, groupMagic...)
89		var tmp [8]byte
90		binary.LittleEndian.PutUint32(tmp[:4], uint32(len(members)))
91		buf = append(buf, tmp[:4]...)
92		offs = make([]int, len(members))
93		lens = make([]int, len(members))
94		for i, m := range members {
95			offs[i] = len(buf)
96			binary.LittleEndian.PutUint64(tmp[:], m.seq)
97			buf = append(buf, tmp[:]...)
98			binary.LittleEndian.PutUint32(tmp[:4], uint32(len(m.records)))
99			buf = append(buf, tmp[:4]...)
100			for _, r := range m.records {
101				binary.LittleEndian.PutUint32(tmp[:4], uint32(len(r)))
102				buf = append(buf, tmp[:4]...)
103				buf = append(buf, r...)
104			}
105			lens[i] = len(buf) - offs[i]
106		}
107		binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(buf))
108		return append(buf, tmp[:4]...), offs, lens
109	}
110	
111	// encodeHoles encodes a hole marker reserving the given sequences
112	// forever. Recovery writes it in place of a torn tail so the reserved
113	// sequences survive as permanent holes across reopens.
114	func encodeHoles(seqs []uint64) []byte {
115		buf := make([]byte, 0, 4+4+8*len(seqs)+4)
116		buf = append(buf, holeMagic...)
117		var tmp [8]byte
118		binary.LittleEndian.PutUint32(tmp[:4], uint32(len(seqs)))
119		buf = append(buf, tmp[:4]...)
120		for _, seq := range seqs {
121			binary.LittleEndian.PutUint64(tmp[:], seq)
122			buf = append(buf, tmp[:]...)
123		}
124		binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(buf))
125		return append(buf, tmp[:4]...)
126	}
127	
128	// decodeBody decodes one batch body (seq + record count + records) as
129	// located by the index. Unlike segment parsing, any inconsistency here
130	// is corruption: an indexed body was validated when the segment was
131	// parsed, so a mismatch means the file changed underneath the log.
132	func decodeBody(body []byte) (uint64, [][]byte, error) {
133		if len(body) < 12 {
134			return 0, nil, ErrCorruptSegment
135		}
136		seq := binary.LittleEndian.Uint64(body[:8])
137		count := binary.LittleEndian.Uint32(body[8:12])
138		records, pos, ok := parseRecords(body, 12, count)
139		if !ok || pos != len(body) {
140			return 0, nil, ErrCorruptSegment
141		}
142		return seq, records, nil
143	}
144	
145	type parsedBatch struct {
146		seq     uint64
147		records [][]byte
148		off     int // offset of the batch body within the segment
149		length  int // length of the batch body
150	}
151	
152	// segmentTail describes an incomplete entry at the end of a segment: the
153	// remnant of a crash in the middle of a write.
154	type segmentTail struct {
155		off  int      // offset where the incomplete entry starts
156		seqs []uint64 // sequences the torn entry had already reserved
157	}
158	
159	// parseSegment decodes every complete entry in data, returning the
160	// committed batches (with the offsets of their bodies, for the index)
161	// and the sequences reserved by hole markers. A truncated tail —
162	// trailing bytes that are only a prefix of an entry — is reported
163	// separately as the signature of a crash mid-write, along with every
164	// sequence the torn entry had already reserved. Any other inconsistency
165	// (unknown magic, bad checksum) yields ErrCorruptSegment.
166	func parseSegment(data []byte) ([]parsedBatch, []uint64, *segmentTail, error) {
167		var batches []parsedBatch
168		var holes []uint64
169		off := 0
170		for off < len(data) {
171			rest := data[off:]
172			if len(rest) < len(segmentMagic) {
