209					return batches, holes, tail, nil
210				}
211				count := binary.LittleEndian.Uint32(rest[4:8])
212				pos := off + 8
213				var members []parsedBatch
214				for i := uint32(0); i < count; i++ {
215					if len(data)-pos < 12 {
216						// Torn between or inside member headers;
217						// recover the member's sequence if whole.
218						if len(data)-pos >= 8 {
219							tail.seqs = append(tail.seqs, binary.LittleEndian.Uint64(data[pos:pos+8]))
220						}
221						return batches, holes, tail, nil
222					}
223					mOff := pos
224					seq := binary.LittleEndian.Uint64(data[pos : pos+8])
225					nrec := binary.LittleEndian.Uint32(data[pos+8 : pos+12])
226					tail.seqs = append(tail.seqs, seq)
227					records, npos, ok := parseRecords(data, pos+12, nrec)
228					if !ok {
229						return batches, holes, tail, nil
230					}
231					pos = npos
232					members = append(members, parsedBatch{seq: seq, records: records, off: mOff, length: pos - mOff})
233				}
234				if len(data)-pos < 4 {
235					return batches, holes, tail, nil
236				}
237				crc := binary.LittleEndian.Uint32(data[pos : pos+4])
238				if crc32.ChecksumIEEE(data[off:pos]) != crc {
239					return nil, nil, nil, ErrCorruptSegment
240				}
241				// Only a complete, checksummed group publishes its
242				// members; a torn group above publishes none.
243				batches = append(batches, members...)
244				off = pos + 4
245			case bytes.Equal(rest[:4], holeMagic):
246				tail := &segmentTail{off: off}
247				if len(rest) < 8 {
248					return batches, holes, tail, nil
249				}
250				count := binary.LittleEndian.Uint32(rest[4:8])
251				pos := off + 8
252				var seqs []uint64
253				for i := uint32(0); i < count; i++ {
254					if len(data)-pos < 8 {
255						tail.seqs = append(tail.seqs, seqs...)
256						return batches, holes, tail, nil
257					}
258					seqs = append(seqs, binary.LittleEndian.Uint64(data[pos:pos+8]))
259					pos += 8
260				}
261				if len(data)-pos < 4 {
262					tail.seqs = append(tail.seqs, seqs...)
263					return batches, holes, tail, nil
264				}
265				crc := binary.LittleEndian.Uint32(data[pos : pos+4])
266				if crc32.ChecksumIEEE(data[off:pos]) != crc {
267					return nil, nil, nil, ErrCorruptSegment
268				}
269				holes = append(holes, seqs...)
270				off = pos + 4
271			default:
272				return nil, nil, nil, ErrCorruptSegment
273			}
274		}
275		return batches, holes, nil, nil
276	}
277	
278	// parseRecords decodes count records starting at pos. ok is false when
279	// the data runs out first, which callers read as a torn write.
280	func parseRecords(data []byte, pos int, count uint32) (records [][]byte, npos int, ok bool) {
281		records = make([][]byte, 0, min(int(count), 1<<20))
282		for i := uint32(0); i < count; i++ {
283			if len(data)-pos < 4 {
284				return nil, 0, false
285			}
286			n := int(binary.LittleEndian.Uint32(data[pos : pos+4]))
287			pos += 4
288			if n < 0 || len(data)-pos < n {
289				return nil, 0, false
290			}
291			rec := make([]byte, n)
292			copy(rec, data[pos:pos+n])
