534	func TestScanSeesConsistentSnapshot(t *testing.T) {
535		l := open(t, t.TempDir(), log.Options{SegmentBytes: 1 << 20})
536		commit(t, l, []byte("one"))
537		commit(t, l, []byte("two"))
538	
539		// Batches committed during a replay are invisible to that replay,
540		// even when the callback itself commits them.
541		var seqs []uint64
542		err := l.Scan(1, func(b log.Batch) error {
543			seqs = append(seqs, b.Seq())
544			if b.Seq() == 1 {
545				commit(t, l, []byte("three"))
546			}
547			return nil
548		})
549		if err != nil {
550			t.Fatalf("Scan: %v", err)
551		}
552		if !reflect.DeepEqual(seqs, []uint64{1, 2}) {
553			t.Fatalf("scan seqs = %v, want [1 2]", seqs)
554		}
555	}
