610	func TestCommitGroup(t *testing.T) {
611		dir := t.TempDir()
612		opts := log.Options{SegmentBytes: 1 << 20, Sync: true}
613		l := open(t, dir, opts)
614	
615		b1, _ := l.Append([][]byte{[]byte("g1a"), []byte("g1b")})
616		b2, _ := l.Append([][]byte{[]byte("g2")})
617		b3, _ := l.Append([][]byte{[]byte("g3")})
618	
619		// A group commits atomically; members keep their reserved sequences.
620		seqs, err := l.CommitGroup([]log.Batch{b1, b3})
621		if err != nil {
622			t.Fatalf("CommitGroup: %v", err)
623		}
624		if !reflect.DeepEqual(seqs, []uint64{1, 3}) {
625			t.Fatalf("group seqs = %v, want [1 3]", seqs)
626		}
627		// b2 was not in the group: still staged.
628		if _, err := l.Read(2); !errors.Is(err, log.ErrNotCommitted) {
629			t.Fatalf("Read(2) err = %v, want ErrNotCommitted", err)
630		}
631		if got, err := l.Read(1); err != nil || !reflect.DeepEqual(got, [][]byte{[]byte("g1a"), []byte("g1b")}) {
632			t.Fatalf("Read(1) = %q, %v", got, err)
633		}
634		if got, err := l.Read(3); err != nil || !reflect.DeepEqual(got, [][]byte{[]byte("g3")}) {
635			t.Fatalf("Read(3) = %q, %v", got, err)
636		}
637		// Replay order follows reserved sequences, not commit order.
638		if _, err := l.Commit(b2); err != nil {
639			t.Fatalf("Commit b2: %v", err)
640		}
641		var got []uint64
642		if err := l.Scan(1, func(b log.Batch) error { got = append(got, b.Seq()); return nil }); err != nil {
643			t.Fatalf("Scan: %v", err)
644		}
645		if !reflect.DeepEqual(got, []uint64{1, 2, 3}) {
646			t.Fatalf("scan = %v, want [1 2 3]", got)
647		}
648		l.Close()
649	
650		// The group survives a reopen exactly once per member: no
651		// duplicates, and the index rebuilt from the segments serves the
652		// same contents the replay sees.
653		l = open(t, dir, opts)
654		got = nil
655		if err := l.Scan(1, func(b log.Batch) error { got = append(got, b.Seq()); return nil }); err != nil {
656			t.Fatalf("Scan after reopen: %v", err)
657		}
658		if !reflect.DeepEqual(got, []uint64{1, 2, 3}) {
659			t.Fatalf("scan after reopen = %v, want [1 2 3]", got)
660		}
661		for seq, want := range map[uint64]string{1: "g1a", 2: "g2", 3: "g3"} {
662			r, err := l.Read(seq)
663			if err != nil || len(r) == 0 || string(r[0]) != want {
664				t.Fatalf("Read(%d) after reopen = %q, %v; want %q", seq, r, err, want)
665			}
666		}
667	}
668	
669	func TestCommitGroupValidation(t *testing.T) {
670		l := open(t, t.TempDir(), log.Options{SegmentBytes: 1 << 20})
671	
672		b1, _ := l.Append([][]byte{[]byte("a")})
673		b2, _ := l.Append([][]byte{[]byte("b")})
674	
675		// A zero-value batch was never staged: the whole group is rejected
676		// and the valid members stay staged.
677		if _, err := l.CommitGroup([]log.Batch{b1, {}}); !errors.Is(err, log.ErrUnknownBatch) {
678			t.Fatalf("CommitGroup err = %v, want ErrUnknownBatch", err)
679		}
680		if _, err := l.Read(1); !errors.Is(err, log.ErrNotCommitted) {
681			t.Fatalf("Read(1) err = %v, want ErrNotCommitted", err)
682		}
683		// A duplicated member is rejected too.
684		if _, err := l.CommitGroup([]log.Batch{b1, b1}); !errors.Is(err, log.ErrUnknownBatch) {
685			t.Fatalf("CommitGroup dup err = %v, want ErrUnknownBatch", err)
686		}
687		// An empty group is a no-op.
688		if seqs, err := l.CommitGroup(nil); err != nil || len(seqs) != 0 {
689			t.Fatalf("CommitGroup(nil) = %v, %v", seqs, err)
690		}
691		// A committed batch cannot be committed again, alone or in a group.
692		if _, err := l.CommitGroup([]log.Batch{b1, b2}); err != nil {
693			t.Fatalf("CommitGroup: %v", err)
694		}
695		if _, err := l.CommitGroup([]log.Batch{b1}); !errors.Is(err, log.ErrUnknownBatch) {
696			t.Fatalf("CommitGroup committed err = %v, want ErrUnknownBatch", err)
697		}
698		if _, err := l.Commit(b2); !errors.Is(err, log.ErrUnknownBatch) {
699			t.Fatalf("Commit committed err = %v, want ErrUnknownBatch", err)
700		}
701	}
702	
703	func TestCommitGroupSegments(t *testing.T) {
704		dir := t.TempDir()
705		l := open(t, dir, log.Options{SegmentBytes: 64})
706	
707		commit(t, l, []byte("one")) // segment 1
708		var bs []log.Batch
709		for _, s := range []string{"g1", "g2", "g3"} {
710			b, err := l.Append([][]byte{[]byte(s)})
711			if err != nil {
712				t.Fatalf("Append: %v", err)
713			}
714			bs = append(bs, b)
715		}
716		if _, err := l.CommitGroup(bs); err != nil {
717			t.Fatalf("CommitGroup: %v", err)
718		}
719		// The whole group lands in one fresh segment.
720		segs := l.Segments()
721		if len(segs) != 2 {
722			t.Fatalf("len(Segments) = %d, want 2: %+v", len(segs), segs)
723		}
724		if segs[0].FirstSeq != 1 || segs[0].LastSeq != 1 {
725			t.Fatalf("segment 0 = %+v, want [1,1]", segs[0])
726		}
727		if segs[1].FirstSeq != 2 || segs[1].LastSeq != 4 {
728			t.Fatalf("group segment = %+v, want [2,4]", segs[1])
729		}
730		l.Close()
731	
732		l = open(t, dir, log.Options{SegmentBytes: 64})
733		segs = l.Segments()
734		if len(segs) != 2 || segs[1].FirstSeq != 2 || segs[1].LastSeq != 4 {
735			t.Fatalf("after reopen Segments = %+v, want [_, [2,4]]", segs)
736		}
737		for seq := uint64(2); seq <= 4; seq++ {
738			if _, err := l.Read(seq); err != nil {
739				t.Fatalf("Read(%d) after reopen: %v", seq, err)
740			}
741		}
742	}
743	
744	// appendTornGroup writes a half-finished group entry reserving seqs to
745	// the end of the last segment file, simulating a crash mid-group-write:
746	// every member but the last is complete, the last is cut off mid-record
747	// and the group checksum is missing.
748	func appendTornGroup(t *testing.T, dir string, seqs ...uint64) {
749		t.Helper()
750		files, err := filepath.Glob(filepath.Join(dir, "*.seg"))
751		if err != nil || len(files) == 0 {
752			t.Fatalf("segment files = %v, %v", files, err)
753		}
754		last := files[len(files)-1]
755		var entry []byte
756		entry = append(entry, 'B', 'C', 'L', 'G')
757		var tmp [8]byte
758		binary.LittleEndian.PutUint32(tmp[:4], uint32(len(seqs)))
759		entry = append(entry, tmp[:4]...)
760		for i, seq := range seqs {
761			binary.LittleEndian.PutUint64(tmp[:], seq)
762			entry = append(entry, tmp[:]...)
763			binary.LittleEndian.PutUint32(tmp[:4], 1) // one record
764			entry = append(entry, tmp[:4]...)
765			if i == len(seqs)-1 {
766				binary.LittleEndian.PutUint32(tmp[:4], 100) // of 100 bytes
767				entry = append(entry, tmp[:4]...)
768				entry = append(entry, []byte("only-a-prefix")...)
769				break
770			}
771			binary.LittleEndian.PutUint32(tmp[:4], 2)
772			entry = append(entry, tmp[:4]...)
773			entry = append(entry, 'x', 'y')
774		}
775		f, err := os.OpenFile(last, os.O_WRONLY|os.O_APPEND, 0)
776		if err != nil {
777			t.Fatal(err)
778		}
779		if _, err := f.Write(entry); err != nil {
780			t.Fatal(err)
781		}
782		if err := f.Close(); err != nil {
783			t.Fatal(err)
784		}
785	}
786	
787	func TestCrashMidGroupIsAllOrNothing(t *testing.T) {
788		dir := t.TempDir()
789		opts := log.Options{SegmentBytes: 1 << 20}
790	
791		l := open(t, dir, opts)
792		commit(t, l, []byte("one"))
793		l.Close()
794	
795		// Power loss halfway through writing a group reserving 2, 3, 4.
796		appendTornGroup(t, dir, 2, 3, 4)
797	
798		l = open(t, dir, opts) // must not fail
799		if got, err := l.Read(1); err != nil || string(got[0]) != "one" {
800			t.Fatalf("Read(1) = %q, %v", got, err)
801		}
802		// No half group: none of the group's batches became visible, and
803		// every reserved sequence is a permanent hole.
804		for seq := uint64(2); seq <= 4; seq++ {
805			if _, err := l.Read(seq); !errors.Is(err, log.ErrNotCommitted) {
806				t.Fatalf("Read(%d) err = %v, want ErrNotCommitted", seq, err)
807			}
808		}
809		b, err := l.Append([][]byte{[]byte("five")})
810		if err != nil {
811			t.Fatalf("Append: %v", err)
812		}
813		if b.Seq() != 5 {
814			t.Fatalf("seq after torn group = %d, want 5", b.Seq())
815		}
816		if _, err := l.Commit(b); err != nil {
817			t.Fatalf("Commit: %v", err)
818		}
819		l.Close()
820	
821		// The holes survive further reopens and are never reused.
822		l = open(t, dir, opts)
823		for seq := uint64(2); seq <= 4; seq++ {
824			if _, err := l.Read(seq); !errors.Is(err, log.ErrNotCommitted) {
825				t.Fatalf("after reopen Read(%d) err = %v, want ErrNotCommitted", seq, err)
826			}
827		}
828		var got []uint64
829		if err := l.Scan(1, func(b log.Batch) error { got = append(got, b.Seq()); return nil }); err != nil {
830			t.Fatalf("Scan: %v", err)
831		}
832		if !reflect.DeepEqual(got, []uint64{1, 5}) {
833			t.Fatalf("scan = %v, want [1 5]", got)
834		}
835		if seq := commit(t, l, []byte("six")); seq != 6 {
836			t.Fatalf("seq = %d, want 6", seq)
837		}
838	}
839	
840	func TestCrashHolePermanentAcrossReopens(t *testing.T) {
841		dir := t.TempDir()
842		opts := log.Options{SegmentBytes: 1 << 20}
843	
844		l := open(t, dir, opts)
845		commit(t, l, []byte("one"))
846		l.Close()
847	
848		// Power loss halfway through writing batch 2.
849		appendTornEntry(t, dir, 2)
850	
851		l = open(t, dir, opts) // recovers and drops the torn entry
852		l.Close()
853	
854		// Reopen again: the hole must not come back as reusable.
855		l = open(t, dir, opts)
856		if _, err := l.Read(2); !errors.Is(err, log.ErrNotCommitted) {
857			t.Fatalf("Read(2) err = %v, want ErrNotCommitted", err)
858		}
859		if seq := commit(t, l, []byte("three")); seq != 3 {
860			t.Fatalf("seq = %d, want 3 (hole 2 must not be reused)", seq)
861		}
862		l.Close()
863	
864		// And again after committing past the hole.
865		l = open(t, dir, opts)
866		if _, err := l.Read(2); !errors.Is(err, log.ErrNotCommitted) {
867			t.Fatalf("after third open Read(2) err = %v, want ErrNotCommitted", err)
868		}
869		var got []uint64
870		if err := l.Scan(1, func(b log.Batch) error { got = append(got, b.Seq()); return nil }); err != nil {
871			t.Fatalf("Scan: %v", err)
872		}
873		if !reflect.DeepEqual(got, []uint64{1, 3}) {
874			t.Fatalf("scan = %v, want [1 3]", got)
875		}
876	}
