	// Power loss halfway through writing batch 2.
	appendTornEntry(t, dir, 2)

	l = open(t, dir, opts) // recovers and drops the torn entry
	l.Close()

	// Reopen again: the hole must not come back as reusable.
	l = open(t, dir, opts)
